"""Español — fe y culto (faith_001 … faith_070)."""

T = {
"faith_001": ("¿Cuántos pilares tiene el islam?", ["5", "4", "6", "7"], "El hadiz de Yibril y el hadiz narrado por Ibn Umar enumeran los cinco pilares del islam."),
"faith_002": ("¿Cómo se llama la declaración de fe en el islam?", ["La Shahada", "La Salat", "El Zakat", "El Hayy"], "La Shahada, el testimonio de fe, es el primer pilar del islam."),
"faith_003": ("¿Cuántas veces al día se realiza la oración obligatoria en el islam?", ["5", "3", "4", "7"], "Las cinco oraciones diarias obligatorias son un pilar fundamental del islam."),
"faith_004": ("¿Cómo se llama la limosna obligatoria en el islam?", ["Zakat", "Sadaqa", "Waqf", "Kaffara"], "El zakat es la limosna obligatoria, uno de los cinco pilares del islam."),
"faith_005": ("¿Cómo se llama el mes de ayuno obligatorio en el islam?", ["Ramadán", "Shawwal", "Rayab", "Muharram"], "El Corán ordena ayunar durante el mes de Ramadán."),
"faith_006": ("¿Cómo se llama la peregrinación a La Meca, obligatoria una vez en la vida para quien pueda?", ["Hayy", "Umra", "I'tikaf", "Tawaf"], "El Corán hace obligatorio el Hayy, al menos una vez en la vida, para quien pueda realizarlo."),
"faith_007": ("¿Hacia qué dirección se orientan los musulmanes para rezar?", ["La Ka'ba, en La Meca", "Jerusalén", "Medina", "El este"], "El Corán estableció la Ka'ba como dirección de la oración (qibla)."),
"faith_008": ("Según un hadiz muy conocido, ¿cuántos artículos de fe (pilares del iman) se enseñan habitualmente?", ["6", "4", "5", "7"], "El hadiz de Yibril enumera seis artículos de fe: Allah, los ángeles, los libros, los mensajeros, el Último Día y el decreto divino."),
"faith_009": ("¿Cómo se llama la purificación con agua que el musulmán hace antes de cada oración?", ["Wudu (ablución)", "Tayammum", "Gusl", "Siwak"], "«Cuando os levantéis para la oración, lavaos la cara y las manos…»: eso es el wudu."),
"faith_010": ("Según el Corán, ¿qué hacen los «nobles escribas» (kiraman katibin)?", ["Registran las obras de las personas", "Cargan el Trono", "Guardan el Paraíso", "Traen la lluvia"], "«Sobre vosotros hay guardianes, nobles escribas»: los ángeles registran cada obra."),
"faith_011": ("¿Cuántos bellos nombres de Allah transmite la tradición auténtica?", ["99", "50", "100", "114"], "Un hadiz auténtico narrado por al-Bujari y Muslim menciona noventa y nueve nombres: cien menos uno."),
"faith_012": ("¿Qué significa el nombre de Allah «Ar-Rahman»?", ["El Misericordioso", "El Creador", "El Rey", "El Omnisciente"], "Ar-Rahman, el Misericordioso: Su misericordia abarca todas las cosas."),
"faith_013": ("En Al-Fatiha, ¿de qué día se llama a Allah «Dueño»?", ["Del Día del Juicio", "Del viernes", "Del primer día", "Del día de Arafa"], "«Dueño del Día del Juicio»: el día en que cada uno encuentra sus obras."),
"faith_014": ("¿Qué día de la semana llama el Corán a los creyentes a la oración en común?", ["El viernes", "El lunes", "El sábado", "El domingo"], "«Cuando se llame a la oración el viernes, acudid al recuerdo de Allah.»"),
"faith_015": ("Según el Corán, ¿quién garantiza la preservación del Corán frente a cualquier alteración?", ["Allah mismo", "Solo los ángeles", "Los sabios", "Los reyes"], "«Ciertamente, Nosotros hemos hecho descender el Recuerdo, y Nosotros somos su Guardián.»"),
"faith_016": ("¿Qué declara el Corán sobre la entrada en la religión?", ["No hay coacción en la religión", "Se hace por juramento", "Requiere un testigo", "Ocurre en la edad adulta"], "«No hay coacción en la religión: la guía recta se distingue del extravío.»"),
"faith_017": ("¿Cuál es el saludo de los musulmanes, un deseo de paz?", ["As-salamu alaykum", "Marhaban", "Sabah al-jayr", "Ahlan wa sahlan"], "«As-salamu alaykum»: la paz sea con vosotros; se responde «wa alaykum as-salam»."),
"faith_018": ("¿Cómo se llama la creencia en la unicidad de Allah, corazón del islam?", ["Tawhid", "Tafsir", "Taywid", "Tarawih"], "El tawhid, afirmar que Allah es Uno, sin asociado, es el fundamento de toda la fe."),
"faith_019": ("¿Qué Libro reveló Allah al profeta Musa?", ["La Tawrat (Torá)", "El Inyil (Evangelio)", "El Zabur (Salmos)", "El Corán"], "«Hicimos descender la Tawrat, en la que hay guía y luz» (5:44)."),
"faith_020": ("¿Qué Libro dio Allah al profeta Isa?", ["El Inyil (Evangelio)", "La Tawrat", "El Zabur", "Las Hojas de Ibrahim"], "«Le dimos el Inyil, en el que hay guía y luz» (5:46)."),
"faith_021": ("Según el Corán, ¿qué se debe hacer al recibir un saludo?", ["Responder con un saludo mejor, o devolverlo", "Quedarse en silencio", "Bajar la mirada", "Responder solo a los amigos"], "«Cuando os saluden, saludad con un saludo mejor, o devolvedlo» (4:86)."),
"faith_022": ("¿La sura Al-A'la menciona «las Hojas» (suhuf) de qué dos profetas?", ["Ibrahim y Musa", "Nuh y Hud", "Dawud y Sulayman", "Zakariyya y Yahya"], "«Esto está en las Hojas primeras, las Hojas de Ibrahim y de Musa» (87:18-19)."),
"faith_023": ("¿Cómo se llama el ángel guardián del Infierno, mencionado en el Corán?", ["Malik", "Ridwan", "Mika'il", "Israfil"], "La gente del Infierno gritará: «¡Oh Malik, que tu Señor acabe con nosotros!» (43:77)."),
"faith_024": ("Según la sura Al-Haqqa, ¿cuántos ángeles cargarán el Trono de Allah el Día de la Resurrección?", ["Ocho", "Cuatro", "Doce", "Uno"], "«Y ese Día, ocho llevarán sobre ellos el Trono de tu Señor» (69:17)."),
"faith_025": ("Según el Corán, ¿quién está encargado de tomar las almas en el momento de la muerte?", ["El ángel de la muerte", "Yibril", "El profeta", "Los genios"], "«Di: el ángel de la muerte, encargado de vosotros, tomará vuestras almas» (32:11)."),
"faith_026": ("¿De qué fueron creados los ángeles, según un hadiz de Sahih Muslim?", ["De luz", "De fuego", "De arcilla", "De agua"], "«Los ángeles fueron creados de luz, los genios de fuego sin humo, y Adam de lo que se os ha descrito.»"),
"faith_027": ("¿De qué fueron creados los genios, según el Corán?", ["De fuego sin humo", "De luz", "De arcilla", "De viento"], "«Y creó a los genios de una llama de fuego sin humo» (55:15)."),
"faith_028": ("¿A quién señala el Corán como enemigo declarado del ser humano?", ["A Satanás (ash-Shaytan)", "A los ángeles", "A los animales", "A la noche"], "«Ciertamente, Satanás es vuestro enemigo; tomadlo, pues, como enemigo» (35:6)."),
"faith_029": ("¿Cuántos profetas son llamados «Ulu al-Azm» (los dotados de firmeza)?", ["Cinco: Nuh, Ibrahim, Musa, Isa y Muhammad ﷺ", "Tres", "Diez", "Veinticinco"], "«Sé paciente como lo fueron los mensajeros dotados de firmeza» (46:35); la sura Ash-Shura (42:13) nombra a estos cinco juntos."),
"faith_030": ("¿En qué se soplará para anunciar la Resurrección, según el Corán?", ["En la Trompeta (as-Sur)", "En un cuerno de carnero", "En una flauta", "En una campana"], "«Se soplará en la Trompeta, y quienes estén en los cielos y en la tierra caerán fulminados… luego se soplará de nuevo» (39:68)."),
"faith_031": ("¿Cómo llama el Corán a lo que pesará las obras el Día de la Resurrección?", ["Las balanzas (al-Mawazin)", "El registro", "El puente", "La trompeta"], "«Pondremos las balanzas justas el Día de la Resurrección; nadie será tratado injustamente en nada» (21:47)."),
"faith_032": ("¿Qué nombre da el Corán al grado más alto del Paraíso, prometido a quienes creen y obran bien?", ["Al-Firdaws", "Al-Kawzar", "As-Sirat", "Al-A'raf"], "«Quienes creen y obran bien tendrán por morada los Jardines del Firdaws» (18:107)."),
"faith_033": ("¿Cuál es el nombre más frecuente del Infierno en el Corán?", ["Yahannam", "Firdaws", "Kawzar", "Tasnim"], "El Corán llama al Infierno «Yahannam» decenas de veces, por ejemplo: «Seréis congregados hacia Yahannam» (3:12)."),
"faith_034": ("¿Qué pilar de la fe afirma el versículo «Hemos creado todas las cosas con medida»?", ["La creencia en el decreto divino (al-qadar)", "La creencia en los ángeles", "La creencia en los Libros", "La creencia en los mensajeros"], "«Hemos creado todas las cosas según una medida (qadar)» (54:49): nada ocurre fuera del conocimiento y la voluntad de Allah."),
"faith_035": ("¿Qué pecado declara Allah que no perdona a quien muere sin arrepentirse de él?", ["El shirk (asociar algo a Allah)", "La mentira", "La avaricia", "La ira"], "«Allah no perdona que se Le asocie nada, y perdona lo que es menor que eso a quien Él quiere» (4:48)."),
"faith_036": ("Según el Corán, ¿a quiénes ama Allah entre los que han pecado?", ["A los que se arrepienten", "A los que ocultan sus pecados", "A los que desesperan", "A los que culpan a otros"], "«Ciertamente, Allah ama a los que se arrepienten y ama a los que se purifican» (2:222)."),
"faith_037": ("Según la sura Nuh, ¿qué trae a un pueblo pedir perdón (istigfar)?", ["Lluvia abundante y bendiciones", "Nada en absoluto", "Una sequía", "Un largo sueño"], "«Pedid perdón a vuestro Señor, que es muy Perdonador; enviará sobre vosotros el cielo con lluvia abundante» (71:10-11)."),
"faith_038": ("¿Qué promete el Corán a quien pone su confianza en Allah (tawakkul)?", ["Allah le basta", "Se hará rico", "Nunca enfermará", "Ya no tendrá que trabajar"], "«Y quien confía en Allah, Él le basta» (65:3)."),
"faith_039": ("¿Qué dice Allah sobre la súplica (du'a) en la sura Gafir?", ["«Invocadme, os responderé»", "«Invocad solo de noche»", "«Invocad a los ángeles»", "«La du'a es solo para los profetas»"], "«Vuestro Señor dice: Invocadme, os responderé» (40:60)."),
"faith_040": ("¿Con qué, según el Corán, encuentran sosiego los corazones?", ["Con el recuerdo de Allah (dhikr)", "Con el dinero", "Con el sueño", "Con los viajes"], "«¿No es con el recuerdo de Allah con lo que se sosiegan los corazones?» (13:28)."),
"faith_041": ("¿Cuál es la primera oración obligatoria del día?", ["Al-Fayr (el alba)", "Adh-Dhuhr (mediodía)", "Al-Asr (la tarde)", "Al-Isha (la noche)"], "Las cinco oraciones son, en orden: Fayr, Dhuhr, Asr, Magrib e Isha."),
"faith_042": ("¿Cuántas rak'a tiene la oración obligatoria del Fayr?", ["Dos", "Tres", "Cuatro", "Una"], "El Fayr tiene dos rak'a; el Magrib tres; Dhuhr, Asr e Isha cuatro cada una."),
"faith_043": ("¿Qué oración obligatoria tiene tres rak'a?", ["Al-Magrib", "Al-Fayr", "Adh-Dhuhr", "Al-Isha"], "El Magrib, justo después de la puesta del sol, es la única oración obligatoria de tres rak'a."),
"faith_044": ("¿Cómo se llama la llamada a la oración hecha desde la mezquita?", ["El adhan", "La jutba", "El tasbih", "La talbiya"], "El adhan lo hace el almuédano (mu'adhdhin) antes de cada una de las cinco oraciones."),
"faith_045": ("Según el versículo de la ablución, ¿hasta dónde hay que lavarse los brazos?", ["Hasta los codos", "Hasta las muñecas", "Hasta los hombros", "Solo las manos"], "«Lavaos la cara y las manos hasta los codos, pasaos las manos por la cabeza y lavaos los pies hasta los tobillos» (5:6)."),
"faith_046": ("¿Qué permite el Corán cuando no se encuentra agua para purificarse antes de la oración?", ["El tayammum con tierra limpia", "Rezar sin purificación", "Aplazar la oración al día siguiente", "Lavarse con arena mojada"], "«Si no encontráis agua, recurrid a tierra limpia y pasáosla por la cara y las manos» (5:6)."),
"faith_047": ("¿Cómo se llama el sermón que pronuncia el imam antes de la oración del viernes?", ["La jutba", "El adhan", "La iqama", "El takbir"], "La jutba del viernes se pronuncia en dos partes desde el minbar, antes de la oración."),
"faith_048": ("¿Qué parte de sus ahorros, guardados durante un año entero, entrega el musulmán como zakat?", ["2,5 %", "10 %", "25 %", "1 %"], "El zakat del dinero ahorrado es la cuarta parte del diezmo, el 2,5 %, cuando supera el umbral (nisab) durante un año lunar."),
"faith_049": ("¿Qué limosna particular se debe al final de Ramadán, antes de la oración del Eid?", ["El zakat al-fitr", "El zakat del oro", "El jums", "La kaffara"], "El Profeta ﷺ hizo obligatorio el zakat al-fitr, un sa' de dátiles o cebada, para cada musulmán, pequeño o mayor."),
"faith_050": ("Según el Corán, ¿desde cuándo hasta cuándo dura el ayuno diario de Ramadán?", ["Desde el alba hasta la noche", "Desde el mediodía hasta la tarde", "Desde la salida del sol hasta el mediodía", "Todo el día y toda la noche"], "«Comed y bebed hasta que se distinga el hilo blanco del alba del hilo negro, luego completad el ayuno hasta la noche» (2:187)."),
"faith_051": ("¿Cómo se llama la comida que toma antes del alba quien va a ayunar?", ["El suhur", "El iftar", "La walima", "La aqiqa"], "El Profeta ﷺ dijo: «Tomad el suhur, pues en el suhur hay bendición»."),
"faith_052": ("¿Cómo se llama la comida con la que se rompe el ayuno al ponerse el sol?", ["El iftar", "El suhur", "El tarawih", "El tahayyud"], "El iftar rompe el ayuno en cuanto se pone el sol, a la hora de la oración del Magrib."),
"faith_053": ("¿Cuántas fiestas (Eid) tiene el islam en el año?", ["Dos: el Eid al-Fitr y el Eid al-Adha", "Solo una", "Cuatro", "Doce"], "El Eid al-Fitr cierra el mes de Ramadán; el Eid al-Adha cae el 10 de Dhul-Hiyya, durante la peregrinación."),
"faith_054": ("¿Qué acontecimiento conmemora el Eid al-Adha?", ["El sacrificio de Ibrahim, rescatado con un carnero", "El nacimiento del Profeta ﷺ", "La batalla de Badr", "La revelación del Corán"], "Dispuesto a sacrificar a su hijo, Ibrahim lo vio rescatado: «Lo rescatamos con un gran sacrificio» (37:107)."),
"faith_055": ("¿En qué mes del calendario islámico tiene lugar la peregrinación (hayy)?", ["Dhul-Hiyya", "Ramadán", "Muharram", "Rayab"], "El hayy se realiza del 8 al 13 de Dhul-Hiyya, el duodécimo y último mes del año lunar."),
"faith_056": ("¿Qué día de Dhul-Hiyya se detienen los peregrinos en la llanura de Arafat?", ["El 9", "El 1", "El 10", "El 27"], "La estancia en Arafat, el 9 de Dhul-Hiyya, es el pilar central del hayy; el Eid al-Adha llega al día siguiente."),
"faith_057": ("¿Cuántas vueltas alrededor de la Ka'ba tiene un tawaf?", ["Siete", "Tres", "Cinco", "Diez"], "El tawaf son siete vueltas alrededor de la Ka'ba, en sentido contrario a las agujas del reloj, empezando en la Piedra Negra."),
"faith_058": ("¿Cuántos recorridos entre As-Safa y Al-Marwa tiene el sa'y?", ["Siete", "Dos", "Cuatro", "Doce"], "El sa'y recuerda la búsqueda de agua de Hayar para Isma'il: siete recorridos, de Safa a Marwa y vuelta, contando cada sentido."),
"faith_059": ("¿Cómo se llama el estado de consagración en el que entra el peregrino, con sus dos telas blancas?", ["El ihram", "El tawaf", "El wuquf", "La talbiya"], "En ihram, el hombre viste dos telas sin coser y el peregrino se abstiene de perfume, caza y disputas."),
"faith_060": ("¿Con qué palabras empieza la talbiya, que los peregrinos repiten camino de La Meca?", ["«Labbayka Allahumma labbayk» (Aquí estoy, oh Allah, aquí estoy)", "«Allahu akbar»", "«Subhana Allah»", "«Al-hamdu li-Llah»"], "La talbiya del Profeta ﷺ era: «Labbayka Allahumma labbayk, labbayka la sharika laka labbayk…»."),
"faith_061": ("¿Qué hacen los peregrinos en Mina cuando lanzan piedrecitas contra tres pilares?", ["La lapidación de las yamarat", "El tawaf", "El sa'y", "La estancia en Arafat"], "El ramy al-yamarat recuerda a Ibrahim ahuyentando a Satanás con piedras; se hace en Mina los días del Eid."),
"faith_062": ("¿Dónde está la Piedra Negra (al-Hayar al-Aswad)?", ["En una esquina de la Ka'ba", "En el monte Arafat", "En Medina", "En la cima del monte Hira"], "Engastada en la esquina oriental de la Ka'ba, marca el punto de partida de cada vuelta del tawaf."),
"faith_063": ("¿Cómo se llama la gran tela negra que cubre la Ka'ba?", ["La kiswa", "El hiyab", "El minbar", "El mihrab"], "La kiswa, bordada con versículos en hilo de oro, se reemplaza cada año durante la peregrinación."),
"faith_064": ("¿Cómo se llama la peregrinación «menor» a La Meca, que puede hacerse en cualquier momento del año?", ["La umra", "El hayy", "La hégira", "La ziyara"], "La umra consta de ihram, tawaf y sa'y; a diferencia del hayy, no está ligada a un mes concreto."),
"faith_065": ("¿Qué significa el nombre de Allah «Al-Jaliq»?", ["El Creador", "El Perdonador", "El Proveedor", "El Rey"], "«Él es Allah, el Creador (al-Jaliq), el Iniciador, el Formador» (59:24)."),
"faith_066": ("¿Qué significa el nombre de Allah «Al-Gafur»?", ["El que perdona mucho", "El Creador", "El Todopoderoso", "El Generoso"], "«No desesperéis de la misericordia de Allah… Él es el Perdonador (al-Gafur), el Misericordioso» (39:53)."),
"faith_067": ("¿Qué significan los dos nombres de Allah «As-Sami'» y «Al-Basir»?", ["El que todo lo oye y el que todo lo ve", "El Rey y el Juez", "El Creador y el Proveedor", "El Primero y el Último"], "El versículo del Viaje Nocturno termina: «Él es el Oyente (as-Sami'), el Vidente (al-Basir)» (17:1)."),
"faith_068": ("¿Qué significa «As-Samad», nombre de Allah en la sura Al-Ijlas?", ["Aquel de quien todo depende y que no depende de nada", "El que perdona", "El que oye", "El que crea"], "«Allahu as-Samad» (112:2): el Señor absoluto a quien todas las criaturas acuden en sus necesidades."),
"faith_069": ("¿Qué dos nombres de Allah abren el Versículo del Trono, justo después de «Allah, no hay dios sino Él»?", ["Al-Hayy y Al-Qayyum (el Viviente, el Subsistente)", "Ar-Rahman y Ar-Rahim", "Al-Malik y Al-Quddus", "Al-Aziz y Al-Hakim"], "«¡Allah! No hay dios sino Él, el Viviente, el Subsistente» (2:255)."),
"faith_070": ("¿Qué significa el nombre de Allah «Ar-Razzaq»?", ["El Gran Proveedor", "El Perdonador", "El Justo", "El Sutil"], "«Ciertamente, Allah es el Proveedor (ar-Razzaq), el Dueño de la fuerza, el Firme» (51:58)."),
}
